         return false;
       }

+      // Don't inline a parameter reference if the containing function
+      // modifies the arguments object, since arguments[i] is an alias for
+      // the i-th parameter.
+      Node value = initialization.getAssignedValue();
+      if (value != null && value.getType() == Token.NAME) {
+        Scope initScope = initialization.getScope();
+        if (initScope != null && argumentsModifiedInScope(initScope)) {
+          // Check if value is a parameter of this scope
+          String varName = value.getString();
+          Var var = initScope.getVar(varName);
+          if (var != null && isParameter(var)) {
+            return false;
+          }
+        }
+      }
+
