     }

+    /**
+     * Checks if the given scope modifies the arguments object.
+     * If arguments is modified, we cannot safely inline parameters.
+     */
+    private boolean argumentsModifiedInScope(Scope scope) {
+      Node scopeNode = scope.getRootNode();
+      if (scopeNode == null) {
+        return false;
+      }
+      return argumentsModifiedInNode(scopeNode);
+    }
+
+    private boolean argumentsModifiedInNode(Node n) {
+      if (n.getType() == Token.ASSIGN) {
+        Node lhs = n.getFirstChild();
+        // Check for arguments[x] = ... or arguments.x = ...
+        if (lhs.getType() == Token.GETELEM || lhs.getType() == Token.GETPROP) {
+          Node obj = lhs.getFirstChild();
+          if (obj.getType() == Token.NAME && "arguments".equals(obj.getString())) {
+            return true;
+          }
+        }
+      }
+      // Only search within the current function scope, not nested scopes
+      for (Node child = n.getFirstChild(); child != null; child = child.getNext()) {
+        if (child.getType() != Token.FUNCTION) {
+          if (argumentsModifiedInNode(child)) {
+            return true;
+          }
+        }
+      }
+      return false;
+    }
+
